🐛 Describe the bug
Using a complex valued model converges on single GPU, but does not converge when using DDP. It appears that the imaginary component of the gradient is always zero with DDP. Wrapping in no_sync() and performing a manual all-reduce seems to circumvent this issue. There are three cases to observe in the following script 1) single GPU, 2) DDP, 3) DDP with manual reduce:

torchrun test.py
torchrun test.py --ddp
torchrun test.py --ddp --manual-reduce

Related issues:
#71613
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader, DistributedSampler
import torch.distributed as dist
import torch.multiprocessing as mp
import os
import argparse
import torch.nn.functional as F

class ComplexToyDataset(Dataset):
    def __init__(self, n_samples=10000, input_dim=4, noise_std=0.01):
        self.input_dim = input_dim

        real = torch.randn(n_samples, input_dim)
        imag = torch.randn(n_samples, input_dim)
        self.x = torch.complex(real, imag)  # Shape: (n_samples, input_dim)

        z1 = self.x[:, 0]
        z2 = self.x[:, 1]
        y = (z1 ** 2) + torch.sin(z2) + (0.5 * z1 * z2.conj())

        noise = torch.randn(n_samples, dtype=torch.cfloat) * noise_std
        self.y = (y + noise).unsqueeze(1)  # Shape: (n_samples, 1)

    def __len__(self):
        return len(self.x)

    def __getitem__(self, idx):
        return self.x[idx], self.y[idx]

class CModReLU(nn.Module):
    def __init__(self):
        super().__init__()
        self.b = nn.Parameter(torch.tensor(1e-5))

    def forward(self, x):
        return F.relu(torch.abs(x) + self.b) * torch.exp(1.j * torch.angle(x))

class ComplexLinear(nn.Module):
    def __init__(self, in_features, out_features):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features, dtype=torch.cfloat))
        self.bias = nn.Parameter(torch.randn(out_features, dtype=torch.cfloat))

    def forward(self, x):
        return torch.matmul(x, self.weight.t()) + self.bias

class ComplexModel(nn.Module):
    def __init__(self, input_dim=4):
        super().__init__()
        self.fc1 = ComplexLinear(input_dim, 8)
        self.fc2 = ComplexLinear(8, 1)
        self.act = CModReLU()

    def forward(self, x):
        x = self.act(self.fc1(x)) 
        return self.fc2(x)

def train(rank, world_size, use_ddp, manual_reduce):
    if use_ddp:
        dist.init_process_group("nccl", rank=rank, world_size=world_size)

    dataset = ComplexToyDataset()
    sampler = DistributedSampler(dataset, num_replicas=world_size, rank=rank) if use_ddp else None
    dataloader = DataLoader(dataset, batch_size=32, sampler=sampler, shuffle=False)

    model = ComplexModel()
    device = torch.device(f"cuda:{rank}" if torch.cuda.is_available() else "cpu")
    model.to(device)

    if use_ddp:
        model = nn.parallel.DistributedDataParallel(model, device_ids=None if not torch.cuda.is_available() else [rank])

    criterion = lambda y_pred, y_true: torch.mean(torch.abs(y_pred - y_true) ** 2)
    optimizer = optim.AdamW(model.parameters(), lr=1e-3)

    for epoch in range(100):
        grad_stats = {}
        running_loss = 0
        for batch_idx, (x, y) in enumerate(dataloader):
            x, y = x.to(device), y.to(device)
            optimizer.zero_grad()
            if use_ddp and manual_reduce:
                with model.no_sync():
                    out = model(x)
                    loss = criterion(out, y)
                    loss.backward()
            else:
                out = model(x)
                loss = criterion(out, y)
                loss.backward()

            if use_ddp and manual_reduce:
                for param in model.parameters():
                    if param.grad is not None:
                        dist.all_reduce(param.grad.data, op=dist.ReduceOp.SUM)

            for name, param in model.named_parameters():
                if torch.is_complex(param):
                    if param.grad is not None:
                        real_mean = param.grad.real.mean().item()
                        imag_mean = param.grad.imag.mean().item()
                        grad_stats.setdefault(name, []).append((real_mean, imag_mean))

            optimizer.step()
            running_loss += (loss.item() - running_loss) / (batch_idx + 1)

        if rank == 0 or not use_ddp:
            print(f"Epoch {epoch}, Running Loss: {running_loss:.4f}")
            print(f"\nEpoch {epoch} gradient stats:")
            for name, values in grad_stats.items():
                real_vals = [v[0] for v in values]
                imag_vals = [v[1] for v in values]
                avg_real = sum(real_vals) / len(real_vals)
                avg_imag = sum(imag_vals) / len(imag_vals)
                print(f"  {name}: avg grad real = {avg_real:.4e}, avg grad imag = {avg_imag:.4e}")

    if use_ddp:
        dist.destroy_process_group()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--ddp", action="store_true", help="Use DistributedDataParallel")
    parser.add_argument("--manual-reduce", action="store_true")
    parser.add_argument("--world_size", type=int, default=2, help="Number of processes for DDP")
    args = parser.parse_args()

    if args.ddp:
        mp.spawn(train, args=(args.world_size, True, args.manual_reduce), nprocs=args.world_size, join=True)
    else:
        train(rank=0, world_size=1, use_ddp=False, manual_reduce=False)

if __name__ == "__main__":
    main()
